"""Generate self-contained shell artifacts; --check detects stale copies."""
from pathlib import Path
import sys

source = Path('scripts/standalone_distribution.py').read_text()
for name, argument in [('install-standalone.sh', ''), ('uninstall-standalone.sh', '--uninstall')]:
    text = '''#!/bin/sh
# Generated by scripts/embed-standalone.py; edit scripts/standalone_distribution.py.
set -eu
command -v python3 >/dev/null || { echo 'Python >=3.11 with pip/venv required' >&2; exit 1; }
python3 -c 'import sys; assert sys.version_info >= (3,11), "Python >=3.11 required"'
bootstrap=$(mktemp -d)
trap 'rm -rf "$bootstrap"' EXIT HUP INT TERM
python3 -m venv "$bootstrap/venv" || { echo 'Install python3-venv and python3-pip' >&2; exit 1; }
"$bootstrap/venv/bin/python" -m pip install --quiet 'PyYAML>=6' 'packaging>=23'
cat > "$bootstrap/distribution.py" <<'PYTHON_DISTRIBUTION'
''' + source + '''PYTHON_DISTRIBUTION
"$bootstrap/venv/bin/python" "$bootstrap/distribution.py" ''' + argument + ' --script-path "$0"\n'
    path = Path(name)
    if '--check' in sys.argv:
        assert path.read_text() == text, f'Stale {name}'
    else:
        path.write_text(text)
        path.chmod(0o755)
